/**
 * A live campaign's pictures, kept on this device (offer presentation spec
 * §8.3): when the plan names a campaign, its pictures for this screen size
 * are fetched into the service worker's `campaign-assets` cache, so the art
 * is there offline and on the first frame; a day after the campaign ends
 * they are deleted. Which pictures are kept is remembered in IndexedDB
 * (meta `campaignAssets`), never in localStorage. Best effort: a browser
 * without the Cache API, or a failed fetch, changes nothing on screen.
 */
import type { ApiBillingState, ApiResolvedCreative } from '@/api/types.js';
import { getMeta, setMeta } from '@/db/schema.js';

/** The service worker's cache for campaign art (vite.config.ts runtimeCaching). */
export const CAMPAIGN_CACHE = 'campaign-assets';

/** How long after a campaign ends its pictures are kept (§8.3: "deleted a day after endsAt"). */
export const CAMPAIGN_ASSET_GRACE_MS = 86_400_000;

/** The pictures worth prefetching: per image, the smallest source at least this wide on screen. */
export function assetsToKeep(creative: ApiResolvedCreative, screenWidth: number): string[] {
  const want = Math.ceil(screenWidth * 2);
  return creative.images.flatMap((image) => {
    const best = ['avif', 'webp', 'jpeg', 'png'].flatMap((format) => {
      const sources = image.sources.filter((one) => one.format === format).sort((a, b) => a.width - b.width);
      const pick = sources.find((one) => one.width >= want) ?? sources[sources.length - 1];
      return pick === undefined ? [] : [pick.url];
    });
    return best;
  });
}

function campaignsOf(state: ApiBillingState): { creative: ApiResolvedCreative; until: string | undefined }[] {
  const out: { creative: ApiResolvedCreative; until: string | undefined }[] = [];
  if (state.offer?.creative !== undefined)
    out.push({ creative: state.offer.creative, until: state.offer.closesAt });
  if (state.campaign !== undefined) out.push({ creative: state.campaign, until: state.campaign.endsAt });
  return out;
}

/** Fetches a live campaign's pictures into the cache, and prunes the ones whose time has gone. */
export async function keepCampaignAssets(state: ApiBillingState, now: Date = new Date()): Promise<void> {
  if (typeof caches === 'undefined' || typeof window === 'undefined') return;
  try {
    const kept = { ...(await getMeta('campaignAssets')) };
    const live = campaignsOf(state);
    // Nothing live and nothing kept: nothing to do, nothing written.
    if (live.length === 0 && Object.keys(kept).length === 0) return;
    const cache = await caches.open(CAMPAIGN_CACHE);
    for (const { creative, until } of live) {
      const ends = until === undefined ? Number.NaN : Date.parse(until);
      const expires = new Date(
        (Number.isNaN(ends) ? now.getTime() : ends) + CAMPAIGN_ASSET_GRACE_MS,
      ).toISOString();
      for (const url of assetsToKeep(creative, window.innerWidth)) {
        if (kept[url] === undefined) {
          // no-cors: the art is another origin's and is only ever drawn, never read.
          await cache.add(new Request(url, { mode: 'no-cors' })).catch(() => undefined);
        }
        kept[url] = expires;
      }
    }
    const still: Record<string, string> = {};
    for (const [url, expires] of Object.entries(kept)) {
      if (Date.parse(expires) <= now.getTime()) await cache.delete(url).catch(() => false);
      else still[url] = expires;
    }
    await setMeta('campaignAssets', still);
  } catch {
    // Art is decoration; the house illustration is always there.
  }
}
